from collections import Counter


class Statistics:
    def __init__(self, data):
        self.data = list(data)

    def count(self):
        return len(self.data)

    def sum(self):
        return sum(self.data)

    def min(self):
        return min(self.data)

    def max(self):
        return max(self.data)

    def range(self):
        return self.max() - self.min()

    def mean(self):
        return round(self.sum() / self.count())

    def median(self):
        sorted_data = sorted(self.data)
        n = len(sorted_data)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_data[mid - 1] + sorted_data[mid]) / 2
        return sorted_data[mid]

    def mode(self):
        counts = Counter(self.data)
        mode_value, mode_count = counts.most_common(1)[0]
        return {'mode': mode_value, 'count': mode_count}

    def var(self):
        mean = self.sum() / self.count()
        squared_diffs = sum((x - mean) ** 2 for x in self.data)
        return round(squared_diffs / self.count(), 1)

    def std(self):
        return round(self.var() ** 0.5, 1)

    def percentile(self, p):
        sorted_data = sorted(self.data)
        idx = int(p / 100 * len(sorted_data))
        if idx >= len(sorted_data):
            idx = len(sorted_data) - 1
        return sorted_data[idx]

    def freq_dist(self):
        counts = Counter(self.data)
        n = self.count()
        return [(round(c / n * 100, 2), v) for v, c in counts.most_common()]
